return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ne_NP','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-27T08:44:12+00:00','po-revision-date'=>'2026-09-27T08:44:12+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'बहुभाषी WordPress, प्रति भाषा एउटा पोष्ट: पोष्टहरू, पृष्ठहरू, श्रेणीहरू, मिडिया पाठ, विजेटहरू र साइट शीर्षकका लिङ्क गरिएका अनुवादहरू, तपाईंको पुरानो Tranzly अनुवादहरू आयात गरिएका छन्।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI प्रदायकहरू','The makers of ChatGPT. A good all-rounder.'=>'ChatGPT का निर्माताहरू। एक राम्रो चौतर्फी।','The makers of Claude. Strong at writing and careful reasoning.'=>'Claude का निर्माताहरू। लेखन र तार्किक विश्लेषणमा उत्कृष्ट।','Google\'s Gemini models. Fast and inexpensive.'=>'Google को Gemini मोडलहरू। छिटो र किफायती।','A European AI company with fast, inexpensive models.'=>'छिटो र किफायती मोडेलहरू भएको एक युरोपेली एआई कम्पनी।','Low-cost models that are good at writing and code.'=>'लेखन र कोडिङमा राम्रा कम लागतका मोडेलहरू।','One key for models from many different providers.'=>'धेरै विभिन्न प्रदायकहरूका मोडलहरूको लागि एउटा मात्र कुञ्जी।','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'OpenAI को एपीआई जस्तै काम गर्ने कुनै पनि सेवा, जसमा तपाईंको आफ्नै कम्प्युटर वा सर्भरमा चलिरहेको मोडेल पनि पर्दछ।','General (used when nothing more specific is set)'=>'सामान्य (कुनै विशिष्ट कुरा सेट नभएको बेला प्रयोग गरिन्छ)','Writing and rewriting'=>'लेख्दै र पुनलेख्दै','Translation'=>'अनुवाद','Code and CSS'=>'कोड र CSS','Sorry, you are not allowed to access this page.'=>'माफ गर्नुहोस्, तपाईंलाई यो पृष्ठ पहुँच गर्ने अनुमति छैन।','These settings are shared by every plugin that uses them: %s.'=>'यी सेटिङहरू तिनीहरूलाई प्रयोग गर्ने हरेक प्लगइनद्वारा साझा गरिएका छन्: %s।','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'तपाईंका कुञ्जीहरू यस साइटको डेटाबेसमा इन्क्रिप्ट गरिएका हुन्छन् र तपाईंले छान्नुभएको प्रदायकलाई मात्र पठाइन्छ—हामीलाई कहिल्यै पनि पठाइँदैन।','Step 1 of 2: choose an AI provider'=>'चरण १ को २: एआई प्रदायक छान्नुहोस्','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'तपाईं आफ्नो कुञ्जी ल्याउनुहुन्छ, त्यसैले तपाईंले प्रयोग गर्नुभएको कुराको लागि प्रदायकलाई सीधै भुक्तानी गर्नुहुन्छ। निश्चित हुनुहुन्न? यीमध्ये कुनै पनि राम्रोसँग काम गर्छ; तपाईंले पछि थप थप्न सक्नुहुन्छ।','Next'=>'पछिल्लो','Step 2 of 2: connect %s'=>'चरण २ को २: %s जडान गर्नुहोस्','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'तपाईंको OpenAI-संगत सेवाको ठेक्का प्रविष्ट गर्नुहोस्, जुन /v1 मा अन्त्य हुन्छ। कुञ्जी तब मात्र आवश्यक हुन्छ जब सेवाले यसको माग गर्दछ।','Open %s and sign in (or create a free account).'=>'%s खोल्नुहोस् र साइन इन गर्नुहोस् (वा निःशुल्क खाता सिर्जना गर्नुहोस्)।','the %s API keys page'=>'%s API कुञ्जीहरूको पृष्ठ','Create a new key and copy it.'=>'एउटा नयाँ कुञ्जी सिर्जना गर्नुहोस् र यसलाई प्रतिलिपि गर्नुहोस्।','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'यसलाई तल टाँस्नुहोस् र "Save and test" मा थिच्नुहोस्। यो काम गर्छ कि गर्दैन भनेर जाँच गर्न हामी एउटा सानो अनुरोध पठाउँछौं।','Most providers need a little credit on the account before a key works: %s.'=>'धेरैजसो प्रदायकहरूलाई कुञ्जी काम गर्नुअघि खातामा केही क्रेडिट आवश्यक पर्छ: %s।','add credit'=>'क्रेडिट थप्नुहोस्','← Choose a different provider'=>'← फरक प्रदायक छान्नुहोस्','Address'=>'ठेगाना','Saved key ends in …%s — paste a new one to replace it'=>'सुरक्षित गरिएको कुञ्जी …%s मा समाप्त हुन्छ — यसलाई बदल्न नयाँ टाँस्नुहोस्','Key (optional)'=>'कुञ्जी (वैकल्पिक)','API key'=>'API कुञ्जी','Save and test'=>'सुरक्षित गर्नुहोस् र परीक्षण गर्नुहोस्','Providers'=>'प्रदायकहरू','Provider'=>'प्रदायक','Status'=>'स्थिति','Key'=>'कुञ्जी','Get a key'=>'एउटा कुञ्जी लिनुहोस्','Test'=>'परीक्षण','Remove'=>'हटाउनुहोस्','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'नयाँ प्लगइन संस्करणद्वारा सुरक्षित गरिएको: यो प्लगइन अपडेट गर्नुहोस्, वा कुञ्जी फेरि प्रविष्ट गर्नुहोस्।','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'सुरक्षित गरिएको कुञ्जी अब खोल्न सकिँदैन (साइटका सुरक्षा कुञ्जीहरू परिवर्तन भएका छन्)। यसलाई फेरि प्रविष्ट गर्नुहोस्।','Not connected'=>'जडान गरिएको छैन','Connected — last test passed %s'=>'जडान भयो — पछिल्लो परीक्षण %s मा सफल भयो','Last test failed: %s'=>'अन्तिम परीक्षण असफल भयो: %s','Connected — not tested yet'=>'जडित — अहिलेसम्म परीक्षण गरिएको छैन','Which model to use'=>'कुन मोडल प्रयोग गर्ने','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ ले त्यो कार्यका लागि हाम्रो सिफारिसलाई जनाउँछ। सूचीमा तपाईंको कुञ्जीले प्रयोग गर्न सक्ने हरेक मोडल समावेश छ, जुन प्रदायकबाट प्रत्यक्ष रूपमा पढिएको हुन्छ।','— Recommended for the provider —'=>'— प्रदायकका लागि सिफारिस गरिएको —','Save models'=>'मोडलहरू सुरक्षित गर्नुहोस्','Refresh the model lists from the providers'=>'प्रदायकहरूबाट मोडेल सूचीहरू रिफ्रेस गर्नुहोस्','best quality'=>'सर्वोत्तम गुणस्तर','lowest cost'=>'सबsthan कम लागत','fastest'=>'सबभन्दा छिटो','Add a model yourself'=>'आफैंले एउटा मोडल थप्नुहोस्','A model came out today? Paste its exact name to use it straight away.'=>'आज एउटा नयाँ मोडेल आयो? यसलाई तुरुन्तै प्रयोग गर्न यसको ठ्याक्कै नाम पेस्ट गर्नुहोस्।','Model name'=>'मोडेलको नाम','Add model'=>'मोडेल थप्नुहोस्','Recommended models list'=>'सिफारिस गरिएका मोडेलहरूको सूची','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'सिफारिस गरिएका मोडेलहरूको सूची प्रमाणित गर्न सकिएन, त्यसैले कुनै पनि सिफारिसहरू देखाइएको छैन। प्लगइन पुनः स्थापना गर्नुहोस्, वा तलका दैनिक अद्यावधिकहरू चालू गर्नुहोस्।','The list in use was published on %s. Each plugin update brings a fresh one.'=>'प्रयोगमा रहेको सूची %s मा प्रकाशित गरिएको थियो। प्रत्येक प्लगइन अपडेटले नयाँ सूची ल्याउँछ।','Also check Zinn Digital® once a day for an updated list.'=>'अद्यावधिक सूचीका लागि दिनमा एक पटक Zinn Digital® पनि जाँच गर्नुहोस्।','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'केवल एउटा साधारण डाउनलोड अनुरोध पठाइन्छ: कुनै कुञ्जी छैन, कुनै साइट ठेगाना छैन, तपाईंको सामग्रीको बारेमा केही छैन। सूचीमा हस्ताक्षर गरिएको हुन्छ, र हस्ताक्षर जाँचमा असफल हुने सूचीलाई बेवास्ता गरिन्छ।','Last checked %1$s: %2$s.'=>'अन्तिम पटक जाँच गरिएको %1$s: %2$s।','Save, and check now if turned on'=>'सुरक्षित गर्नुहोस्, र सक्रिय भए नभएको अहिले जाँच गर्नुहोस्','a newer list was installed'=>'एउटा नयाँ सूची स्थापना गरियो','already up to date'=>'पəहिले नै अद्यावधिक गरिएको छ','the download failed the signature check and was ignored'=>'डाउनलोडले हस्ताक्षर जाँचमा असफल भयो र यसलाई बेवास्ता गरियो','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® लाई सम्पर्क गर्न सकिएन; हालको सूची प्रयोगमा रहन्छ','turned off'=>'बन्द गरिएको','Open'=>'खोल्नुहोस्','Check their status page'=>'तिनीहरूको स्थिति पृष्ठ जाँच गर्नुहोस्','Open your billing page'=>'तपाईंको बिलिङ पृष्ठ खोल्नुहोस्','Open your API keys page'=>'तपाईंको API कुञ्जीहरूको पृष्ठ खोल्नुहोस्','Open the AI settings'=>'AI सेटिङहरू खोल्नुहोस्','Sorry, you are not allowed to do that.'=>'माफ गर्नुहोस्, तपाईँलाई यो गर्न अनुमति छैन।','Unknown provider.'=>'अज्ञात प्रदायक।','Enter the address of your service, for example http://localhost:11434/v1.'=>'तपाईंको सेवाको ठेक्का प्रविष्ट गर्नुहोस्, उदाहरणका लागि http://localhost:11434/v1।','That does not look like an API key. Copy it again, without spaces.'=>'त्यो API कुञ्जी जस्तो देखिँदैन। खाली ठाउँहरू बिना यसलाई फेरि प्रतिलिपि गर्नुहोस्।','Paste your API key first.'=>'पहिले आफ्नो एपीआई कुञ्जी (API key) टाँस्नुहोस्।','Key removed.'=>'कुञ्जी हटाइयो।','Models saved.'=>'मोडेलहरू सुरक्षित गरिएका छन्।','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'नमूनाको सटीक नाम प्रविष्ट गर्नुहोस्, उदाहरणका लागि प्रदायकको कागजातमा लेखिए अनुसार।','Added %s. Choose it under "Which model to use".'=>'%s थपियो। यसलाई "कुन मोडल प्रयोग गर्ने" अन्तर्गत छान्नुहोस्।','Model removed.'=>'मोडल हटाइयो।','Daily updates are off. The list that came with the plugin is used.'=>'दैनिक अपडेटहरू बन्द छन्। प्लगइनमा समावेश सूची प्रयोग गरिएको छ।','Checked: %s.'=>'जाँच गरिएको: %s।','Model lists refreshed.'=>'मोडेल सूचीहरू ताजा गरियो।','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'तपाईंको AI कुञ्जी तपाईंको एउटा प्लगइनको नयाँ संस्करणद्वारा सेभ गरिएको थियो। यो प्लगइन अपडेट गर्नुहोस्, वा AI सेटिङहरूमा कुञ्जी फेरि प्रविष्ट गर्नुहोस्।','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'तपाईंको सेभ गरिएको AI कुञ्जी अब खोल्न सकिंदैन (साइटको सुरक्षा कुञ्जीहरू परिवर्तन भएका छन्)। यसलाई AI सेटिङहरूमा फेरि प्रविष्ट गर्नुहोस्।','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'एआई सेटअप गरिएको छैन। एआई सेटिङहरूमा एआई प्रदायकको लागि कुञ्जी थप्नुहोस्।','No model is chosen for this task. Pick one in the AI settings.'=>'यस कार्यका लागि कुनै पनि मोडल छेन गरिएको छैन। AI सेटिङहरूमा एउटा छान्नुहोस्।','That AI provider is not supported by this version of the plugin.'=>'प्लगइनको यो संस्करणद्वारा त्यो AI प्रदायक समर्थित छैन।','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'यो साइट तपाईंको AI सेवामा पुग्न सकेन। यो चलिरहेको छ भनी र यसको ठेगाना तपाईंको वेब सर्भरबाट पहुँचयोग्य छ भनी जाँच गर्नुहोस् (तपाईँको आफ्नै कम्प्युटरमा रहेको सेवा होस्ट गरिएको साइटबाट पहुँचयोग्य हुँदैन)।','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'यो साइटले %s मा पहुँच गर्न सकेन। तिनीहरूको स्थिति पृष्ठ जाँच गर्नुहोस्; यदि तिनीहरू चालु छन् भने, तपाईंको होस्टले बाहिरी जडानहरू रोकिरहेको हुन सक्छ, वा ठेगाना गलत छ।','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s ले भन्छ कि तपाईंको खातामा कुनै क्रेडिट वा कोटा बाँकी छैन। उनीहरूसँगको आफ्नो खातामा क्रेडिट थप्नुहोस् या सीमा बढाउनुहोस्, त्यसपछि फेरि प्रयास गर्नुहोस्।','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s ले तपाईंको कुञ्जी स्वीकार गरेन। यो गलत टाइप भएको, खारेज गरिएको वा म्याद समाप्त भएको हुन सक्छ। नयाँ कुञ्जी सिर्जना गर्नुहोस् र यहाँ टाँस्नुहोस्।','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ले तपाईंको कुञ्जीका लागि यो अनुरोध अस्वीकार गर्‍यो। कुञ्जीसँग यो मोडेल वा सुविधमा पहुँच नभएको हुन सक्छ, वा तपाईंको खाता प्रमाणित गर्नुपर्ने हुन सक्छ।','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'तपाईंको कुञ्जीका लागि %2$s बाट "%1$s" मोडल उपलब्ध छैन। AI सेटिङहरूमा अर्को मोडल छान्नुहोस्।','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'तपाईंको %2$s योजनामा ​​"%1$s" मोडल समावेश छैन। AI सेटिङहरूमा अर्को मोडल छान्नुहोस्, वा उनीहरूसँग आफ्नो योजना अपग्रेड गर्नुहोस्।','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ले तपाईंको कुञ्जीले अनुरोधहरू पठाउन सक्ने गतिलाई सीमित गर्दैछ। एक मिनेट पर्खनुहोस् र फेरि प्रयास गर्नुहोस्, वा तिनीहरूसँग आफ्नो दर सीमा बढाउनुहोस्।','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s मा अहिले समस्या भइरहेको छ (उनीहरूकोतर्फबाट सेवा अवरुद्ध वा अत्यधिक भार)। तपाईंका सेटिङहरूमा कुनै त्रुटि छैन। केही समयपछि फेरि प्रयास गर्नुहोस्।','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'AI अनुरोध अज्ञात कारणले असफल भयो। फेरि प्रयास गर्नुहोस्; यदि यो भइरह्यो भने, तलका विवरणहरूसँग समर्थन टोलीलाई सम्पर्क गर्नुहोस्।','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'AI प्रदायकले यो प्लगइनले पढ्न नसक्ने रूपमा उत्तर दियो। फेरि प्रयास गर्नुहोस्; यदि यो भइरह्यो भने, अर्को मोडेल छान्नुहोस् वा सहयोगको लागि सम्पर्क गर्नुहोस्।','Custom (OpenAI-compatible)'=>'कस्टम (OpenAI-compatible)','Save a key for this provider first.'=>'पहिले यो प्रदायकका लागि कुञ्जी सुरक्षित गर्नुहोस्।','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'तपाईंको कुञ्जीले काम गर्छ, तर प्रदायकले यसको लागि कुनै पाठ मोडेल सूचीबद्ध गरेको छैन। तल आफैं एउटा मोडेल थप्नुहोस्।','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'जडित। %1$s ले %2$s प्रयोग गरेर जवाफ दिनुभयो। तपाईंको AI सुविधाहरू प्रयोग गर्न तयार छन्।','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'तपाईंको प्रयोगकर्ता भूमिकालाई यो साइटमा एआई प्रयोग गर्ने अनुमति छैन। एक प्रशासकलाई सोध्नुहोस्।','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'यो साइटले आफ्नो मासिक AI खर्च सीमा पुगेको छ। एक प्रशासकले यसलाई AI सेटिङहरूमा बढाउन सक्छन्।','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'यो साइटले AI अनुरोधहरूको मासिक सीमा पार गरेको छ। प्रशासकले AI सेटिङहरूमा यसलाई बढाउन सक्नुहुन्छ।','Usage and cost'=>'प्रयोग र लागत','The log, limits and role permissions apply to AI used through: %s.'=>'लग, सीमाहरू र भूमिकाहरूका अनुमतिहरू %s मार्फत प्रयोग हुने AI मा लागू हुन्छन्।','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'लागतहरू अनुमानित हुन्, प्रकाशित मूल्यहरूबाट हिसाब गरिएका हुन्; कुनै अज्ञात मूल्य भएको मोडेललाई शून्य मानिन्छ।','This month: %1$s requests, about %2$s.'=>'यस महिना: %1$s अनुरोधहरू, लगभग %2$s।','When'=>'कहिले','Who'=>'को हो','Used for'=>'प्रयोग गरिएको','Model'=>'मोडेल','Tokens in / out'=>'टोकन इन / आउट','About'=>'बारेमा','Result'=>'नतिजा','No AI requests have been made yet.'=>'अझैसम्म कुनै पनि एआई (AI) अनुरोधहरू गरिएका छैनन्।','Done'=>'सम्पन्न भयो','Limits and permissions'=>'सीमाहरू र अनुमतिहरू','Monthly spending limit (US dollars)'=>'मासिक खर्च सीमा (US डलर)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'कुनै सीमा नराख्न खाली छोड्नुहोस्। अनुमानित लागत त्यहाँ पुगेktan पछि महिनाको बाँकी अवधिको लागि AI रोकिन्छ।','Monthly request limit'=>'मासिक अनुरोध सीमा','Leave empty for no limit.'=>'कुनै सीमा नराख्न खाली छोड्नुहोस्।','Who may use AI'=>'AI कसले प्रयोग गर्न सक्छ','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'प्लगइनका सुविधाहरू प्रयोग गर्न सक्ने सबैलाई AI प्रयोग गर्न अनुमति दिन कुनै पनि नलगाउनुहोस्। प्रशासकहरूले यसलाई सधैँ प्रयोग गर्न सक्छन्।','Save limits and permissions'=>'सीमा र अनुमतिहरू बचत गर्नुहोस्','Limits and permissions saved.'=>'सीमाहरू र अनुमतिहरू सुरक्षित गरियो।','That language is not one of this site\'s languages.'=>'त्यo भाषा यस साइटका भाषाहरूमध्ये एक होइन।','A translation must be the same kind of content as the original.'=>'अनुवाद मूल सामग्री जस्तै नै प्रकारको हुनुपर्छ।','Choose one of the site\'s other languages.'=>'साइटका अन्य भाषाहरूमध्ये एउटा छान्नुहोस्।','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'यस प्लगइनको प्रतिलिपिबाट प्रशासक स्क्रिनका स्क्रिप्टहरू हराइरहेका छन्। यसलाई जारी गरिएको प्याकेजबाट पुन: स्थापना गर्नुहोस्।','This screen needs JavaScript.'=>'यो स्क्रिनलाई जाभास्क्रिप्ट (JavaScript) आवश्यक छ।','Choose a language'=>'एउटा भाषा छान्नुहोस्','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'उपसर्ग १ देखि ८ वटा साना अक्षर वा अङ्कहरूको हुनुपर्छ, एउटा अक्षरबाट सुरु हुनुपर्छ, र प्लगइनको नाम हुनु हुँदैन।','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" भाषा कोड होइन। fr_FR वा de_DE जस्तो WordPress लोकेल प्रयोग गर्नुहोस्।','List at least one language.'=>'कतीपय एउटा भाषा सूचीबद्ध गर्नुहोस्।','You are not allowed to translate this item.'=>'तपाईंलाई यो वस्तु अनुवाद गर्ने अनुमति छैन।','This item already has a version in that language.'=>'यो वस्तुमा त्यो भाषामा पहिल्यैदेखि एउटा संस्करण छ।','That translation engine is not available on this site.'=>'यो साइटमा त्यो अनुवाद इन्जिन उपलब्ध छैन।','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'प्रत्येक भाषाका लागि भिन्न इन्जिनहरू, स्वचालित फलब्याक र खर्च सीमाहरू Tranzly Pro का विशेषताहरू हुन्।','Each language must be one of the site\'s languages, with an available engine.'=>'प्रत्येक भाषा साइटका भाषाहरूमध्ये एक हुनुपर्छ, जसमा उपलब्ध इन्जिन होस्।','The fallback list may only name available engines.'=>'फलब्याक सूचीले उपलब्ध इन्जिनहरूको मात्र नाम दिन सक्छ।','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'मासिक सीमा उपलब्ध इन्जिनका लागि, शून्य वा सोभन्दा बढी, US डलरमा तय गरिएको रकम हो।','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'मनपर्ने अनुवाद र भाषा अनुसारको टोन Tranzly Pro का विशेषताहरू हुन्। अनुवाद नगरिने सूची (do-not-translate list) निःशुल्क छ।','Glossary entries must be grouped by one of the site\'s languages.'=>'शब्दावली प्रविष्टिहरू साइटको एउटा भाषाद्वारा समूहीकृत गरिनुपर्छ।','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'प्रत्येक साइटको भाषाअनुसार टोन सेट गरिन्छ: औपचारिकता पूर्वनिर्धारित, कम्तिमा वा बढी, साथै वैकल्पिक निर्देशनहरू।','The value for %s is not one of the allowed choices.'=>'%s को मान अनुमति दिएका विकल्पहरू मध्ये एक होइन।','The background queue is not available on this site.'=>'यो साइटमा पृष्ठभूमि क्यु उपलब्ध छैन।','A translation job runs as the person who starts it, so a user must be signed in.'=>'अनुवाद कार्य यसलाई सुरु गर्ने व्यक्तिको रूपमा चल्छ, त्यसैले प्रयोगकर्ताले साइन इन गरेको हुनुपर्छ।','There is nothing you are allowed to translate in that selection.'=>'त्यहाँ त्यो चयनमा तपाईंले अनुवाद गर्न अनुमति पाएको केही पनि छैन।','That item is not part of a translation job.'=>'त्यो वस्तु अनुवाद कार्यको हिस्सा होइन।','You are not allowed to change that translation.'=>'तपाईंलाई त्यो अनुवाद परिवर्तन गर्ने अनुमति छैन।','This item\'s group already has a %1$s version (#%2$d).'=>'यस वस्तुको समूहसँग पहिल्यैदेखि %1$s संस्करण (#%2$d) छ।','An item cannot be its own translation.'=>'एउटा वस्तु आफैंको अनुवाद हुन सक्दैन।','That item is already a translation of something else. Unlink it first.'=>'त्यो वस्तु पहिल्यै अन्य कुिकै अनुवाद हो। पहिले यसको लिङ्क हटाउनुहोस्।','The translation link could not be saved.'=>'अनुवाद लिङ्क सुरक्षित गर्न सकिएन।','That text cannot be translated here.'=>'त्यò पाठ यहाँ अनुवाद गर्न सकिँदैन।','That media text cannot be translated here.'=>'त्यो मिडिया पाठ यहाँ अनुवाद गर्न सकिँदैन।','A translation can be published or kept as a draft.'=>'अनुवादलाई प्रकाशित गर्न सकिन्छ वा मस्यौदाको रूपमा राख्न सकिन्छ।','You are not allowed to publish this kind of content.'=>'तपाईंलाई यस प्रकारको सामग्री प्रकाशित गर्ने अनुमति छैन।','This item is already written in that language.'=>'यो वस्तु पहिल्यै त्यो भाषामा लेखिएको छ।','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'यो अनुवाद कुनै व्यक्तिद्वारा सम्पादन गरिएको (वा आयात गरिएको) हो, त्यसैले यो सुरक्षित छ। यसलाई फेरि अनुवाद गर्न अनलक गर्नुहोस्।','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'अहिलेसम्म कुनै पनि अनुवाद इन्जिन सेटअप गरिएको छैन। Tranzly → Engines मा गएर यसको लागि एउटा कुञ्जी (key) थप्नुहोस्।','That translation engine is not set up yet: add its key first.'=>'त्यो अनुवाद इन्जिन हालसम्म सेटअप गरिएको छैन: पहिले यसको कुञ्जी थप्नुहोस्।','The same text is being translated by another job right now; this item will use that answer.'=>'यही पाठ हाल अर्को कामद्वारा अनुवाद भइरहेको छ; यो वस्तुले त्यही उत्तर प्रयोग गर्नेछ।','No translation engine could take this item.'=>'कुनै पनि अनुवाद इन्जिनले यो वस्तु लिन सकेन।','The engine did not return a translation for every part of this item. Nothing was changed.'=>'इन्जिनले यस वस्तुको प्रत्येक भागको लागि अनुवाद फर्काएन। केही पनि परिवर्तन गरिएको थिएन।','AI model'=>'AI मोडेल','AI model (%1$s %2$s)'=>'AI मोडेल (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s मा अहिले समस्या भइरहेको छ। थोरै समयमा फेरि प्रयास गर्नुहोस्, वा अर्को इन्जिन प्रयोग गर्नुहोस्।','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'तपाईंको साइटले %s सम्म पुग्न सकेन। यसले बाह्य जडानहरू (outgoing connections) गर्न सक्छ भनेर जाँच गर्नुहोस्, त्यसपछि फेरि प्रयास गर्नुहोस्।','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s ले तपाइँको API कुञ्जी स्वीकार गरेन। Tranzly → Engines मा कुञ्जी जाँच गर्नुहोस्।','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'तपाईंको %s खाताको कोटा वा ब्यालेन्स समाप्त भएको छ। तिनीहरूसँग यसलाई टप अप गर्नुहोस्, वा अर्को इन्जिन प्रयोग गर्नुहोस्।','%s asked us to slow down. It will be tried again automatically.'=>'%s ले हामीलाई ढिलो गर्न अनुरोध गरेको छ। यो स्वचालित रूपमा फेरि प्रयास गरिनेछ।','This text is too long for %s in one go. Split the content, or use another engine.'=>'यो पाठ %s को लागि एकै पटकमा धेरै लामो छ। सामग्री विभाजन गर्नुहोस्, वा अर्को इन्जिन प्रयोग गर्नुहोस्।','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s ले यो सामग्री अनुवाद गर्न अस्वीकार गर्यो। अर्को इन्जिन प्रयास गर्नुहोस्, वा यसलाई आफैं अनुवाद गर्नुहोस्।','%s does not translate this language. Choose another engine for it.'=>'%s ले यो भाषा अनुवाद गर्दैन। यसको लागि अर्को इन्जिन छान्नुहोस्।','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'%s को लागि यस महिनाको खर्च सीमा पुगिसकेको छ, त्यसैले यसमा थप केही पठाइएको छैन। Tranzly → Engines मा सीमा बढाउनुहोस्, वा अर्को महिनासम्म पर्नुहोस्।','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'%s सँगको अनुवाद Tranzly ले पहिचान गर्न नसक्ने कारणले असफल भयो। विवरणहरू तल छन्।','An engine id must be lowercase letters, digits and hyphens.'=>'इन्जिन आइडी (engine id) मा साना अक्षरहरू, अङ्कहरू र हाइफनहरू मात्र हुनुपर्छ।','Part of the message telling the user what they should receive via email.a license key'=>'एउटा इजाजतपत्र कुञ्जी','A user has not yet been associated with the license, which is necessary to prevent unauthorized activation. To assign the license to your user, you agree to share your WordPress user\'s full name and email address.'=>'अनुमति नभएको सक्रियता रोक्न आवश्यक पर्ने भएकाले प्रयोगकर्तालाई अहिलेसम्म लाइसेन्ससँग जोडिएको छैन। तपाईंको प्रयोगकर्तालाई लाइसेन्स तोक्नका लागि, तपाईं आफ्नो WordPress प्रयोगकर्ताको पूरा नाम र इमेल ठेगाना साझा गर्न सहमत हुनुहुन्छ।','the above-mentioned sites'=>'माथि उल्लेखित साइटहरू','Account'=>'खाता','Account Details'=>'खाता विवरण','Account is pending activation. Please check your email and click the link to activate your account and then submit the affiliate form again.'=>'खाता सक्रिय हुन बाँकी छ। कृपया आफ्नो इमेल जाँच गर्नुहोस् र आफ्नो खाता सक्रिय गर्न लिङ्क क्लिक गर्नुहोस् र त्यसपछि सम्बद्ध फारम (affiliate form) फेरि पेश गर्नुहोस्।','Would you like to merge %1$s into %2$s?'=>'के तपाईँ %1$s लाई %2$s मा मर्ज (गाभ्न) चाहनुहुन्छ?','Actions'=>'कार्यहरू','Activate'=>'सक्रिय गर्नुहोस्','Activate Free Version'=>'निःशुल्क संस्करण सक्रिय गर्नुहोस्','Activate License'=>'लाइसेन्स सक्रिय गर्नुहोस्','activate a license here'=>'यहाँ लाइसेन्स सक्रिय गर्नुहोस्','Please enter the license key that you received in the email right after the purchase:'=>'तपाईले खरिद गरेलगत्तै इमेलमा प्राप्त गर्नुभएको लाइसेन्स कुञ्जी कृपया प्रविष्ट गर्नुहोस्:','Activate license on all sites in the network.'=>'नेटवर्कका सबै साइटहरूमा लाइसेन्स सक्रिय गर्नुहोस्।','Activate license on all pending sites.'=>'सबै बाँकी साइटहरूमा इजाजतपत्र सक्रिय गर्नुहोस्।',' The paid version of %1$s is already installed. Please activate it to start benefiting from the %2$s features. %3$s'=>'%1$s को सशुल्क संस्करण पहिले नै स्थापित छ। %2$s का सुविधाहरूबाट लाभ उठाउन सुरु गर्न कृपया यसलाई सक्रिय गर्नुहोस्। %3$s',' The paid version of %1$s is already installed. Please navigate to the %2$s to activate it and start benefiting from the %3$s features.'=>'%1$s को सशुल्क संस्करण पहिले नै स्थापित छ। यसलाई सक्रिय गर्न र %3$s का सुविधाहरूको लाभ लिन कृपया %2$s मा जानुहोस्।','Activate this add-on'=>'यो एड-अन सक्रिय गर्नुहोस्','Activate %s'=>'%s सक्रिय गर्नुहोस्','Activate %s features'=>'%s सुविधाहरू सक्रिय गर्नुहोस्','%s - plugin name. As complete "PluginX" activation nowComplete "%s" Activation Now'=>'अहिले "%s" सक्रियता पूरा गर्नुहोस्','Activate %s Plan'=>'%s योजना सक्रिय गर्नुहोस्','Activated'=>'सक्रिय गरिएको','Activating'=>'सक्रिय गर्दै','Activating license'=>'लाइसेन्स सक्रिय गरिँदै छ','Your account was successfully activated with the %s plan.'=>'तपाईंको खाता %s योजनामार्फत सफलतापूर्वक सक्रिय गरियो।','active add-onActive'=>'सक्रिय','Add another domain'=>'अर्को डोमेन थप्नुहोस्','Add-Ons'=>'थप सुविधाहरू','Add Ons for %s'=>'%s का लागि एड अनहरू','We couldn\'t load the add-ons list. It\'s probably an issue on our side, please try to come back in few minutes.'=>'हामी एड-अनहरूको सूची लोड गर्न सक्यौं। यो सम्भवतः हाम्रो तर्फबाट भएको समस्या हो, कृपया केही मिनेटमा फेरि प्रयास गर्नुहोस्।','Add-On'=>'थप सेवा','%s is a premium only add-on. You have to purchase a license first before activating the plugin.'=>'%s केवल प्रिमियम एड-अन हो। प्लगइन सक्रिय गर्नु अघि तपाईंले पहिले इजाजतपत्र खरिद गर्नुपर्छ।','%s Add-on was successfully purchased.'=>'%s एड-अन सफलतापूर्वक खरिद गरियो।','Your %s Add-on plan was successfully upgraded.'=>'तपाईंको %s एड-अन योजना सफलतापूर्वक अपग्रेड गरियो।','%s free trial was successfully cancelled. Since the add-on is premium only it was automatically deactivated. If you like to use it in the future, you\'ll have to purchase a license.'=>'%s नि:शुल्क परीक्षण सफलतापूर्वक रद्दीकरण गरियो। एड-अन प्रिमियम मात्र भएकोले यसलाई स्वचालित रूपमा निस्क्रिय पारियो। यदि तपाईं भविष्यमा यसलाई प्रयोग गर्न चाहनुहुन्छ भने, तपाईंले इजाजतपत्र खरिद गर्नुपर्नेछ।','addonX cannot run...%s cannot run without the plugin.'=>'%s प्लगइन बिना चल्न सक्दैन।','addonX cannot run without pluginY%1$s cannot run without %2$s.'=>'%2$s बिना %1$s चल्न सक्दैन।','Just letting you know that the add-ons information of %s is being pulled from an external server.'=>'तपाईलाई यो जानकारी दिन चाहन्छु कि %s को एड-अन (add-ons) जानकारी बाह्य सर्भरबाट तानिएको छ।','Add Ons of module %s'=>'%s मोड्युलका एड अनहरू','Address Line %d'=>'ठेगाना लाइन %d','Affiliate'=>'सहयोगी','Due to violation of our affiliation terms, we decided to temporarily block your affiliation account. If you have any questions, please contact support.'=>'हाम्रा सहबद्ध सर्तहरूको उल्लङ्घन भएका कारण, हामीले तपाईंको सहबद्ध खाता अस्थायी रूपमा ब्लक गर्ने निर्णय गरेका छौं। यदि तपाइँसँग कुनै प्रश्नहरू छन् भने, कृपया समर्थन टोलीलाई सम्पर्क गर्नुहोस्।','Your affiliation account was temporarily suspended.'=>'तपाईंको सम्बद्ध (affiliation) खाता अस्थायी र